// PicnicFest — Contest Closed mode
// Replaces the full contest server. The contest is over:
// every visitor now sees the "Contest Closed + Winner" page.
// NOTE: the previous full contest server.js is still in git history,
// so the contest can be restored later by reverting this file.
const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

const EMBEDDED_HTML = "<!DOCTYPE html>\n<html lang=\"as\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Contest Closed \u2014 Picnic Moments Contest 2026</title>\n<style>\n  *{margin:0;padding:0;box-sizing:border-box;}\n  body{\n    font-family:system-ui,-apple-system,'Segoe UI',sans-serif;\n    background:radial-gradient(1200px 600px at 50% -10%,#1e3a5f 0%,#0f172a 55%,#0b1120 100%);\n    color:#e2e8f0;min-height:100vh;display:flex;flex-direction:column;align-items:center;\n  }\n  .gamosa-strip{\n    width:100%;height:12px;\n    background:repeating-linear-gradient(90deg,#c53030 0 14px,#fff 14px 20px,#c53030 20px 34px,#fff 34px 40px);\n    box-shadow:0 2px 10px rgba(0,0,0,.5);\n  }\n  .wrap{max-width:560px;width:100%;padding:36px 20px 40px;display:flex;flex-direction:column;align-items:center;text-align:center;}\n  .closed-pill{\n    display:inline-flex;align-items:center;gap:8px;background:rgba(148,163,184,.15);\n    border:1px solid rgba(148,163,184,.35);color:#cbd5e1;border-radius:999px;\n    padding:8px 18px;font-size:.9rem;font-weight:600;letter-spacing:.5px;margin-bottom:18px;\n  }\n  h1{font-size:1.7rem;color:#fff;line-height:1.3;margin-bottom:10px;}\n  .thanks{color:#94a3b8;font-size:.98rem;line-height:1.7;max-width:430px;margin-bottom:34px;}\n  .winner-card{\n    width:100%;background:linear-gradient(180deg,rgba(30,41,59,.92),rgba(15,23,42,.95));\n    border:1px solid rgba(250,204,21,.35);border-radius:22px;padding:34px 22px 30px;\n    box-shadow:0 20px 60px rgba(0,0,0,.45),0 0 0 1px rgba(250,204,21,.08) inset;\n    position:relative;overflow:hidden;\n  }\n  .winner-card::before{\n    content:\"\";position:absolute;top:-70px;left:50%;transform:translateX(-50%);\n    width:260px;height:130px;border-radius:50%;\n    background:radial-gradient(closest-side,rgba(250,204,21,.22),transparent);\n  }\n  .winner-badge{\n    display:inline-block;background:linear-gradient(90deg,#f59e0b,#facc15);\n    color:#422006;font-weight:800;letter-spacing:2px;font-size:.8rem;\n    padding:7px 22px;border-radius:999px;margin-bottom:20px;box-shadow:0 4px 14px rgba(245,158,11,.35);\n  }\n  .photo-ring{\n    width:190px;height:190px;border-radius:50%;padding:5px;margin:0 auto 16px;\n    background:conic-gradient(#f59e0b,#fef08a,#f59e0b,#b45309,#f59e0b);\n    box-shadow:0 10px 40px rgba(245,158,11,.35);\n  }\n  .photo-ring img{\n    width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;border:3px solid #0f172a;\n  }\n  .winner-name{font-size:1.55rem;font-weight:800;color:#fff;margin-bottom:6px;}\n  .prize-line{\n    display:inline-flex;align-items:center;gap:8px;margin-top:10px;\n    background:rgba(250,204,21,.12);border:1px solid rgba(250,204,21,.4);\n    color:#fde047;font-weight:700;font-size:1.05rem;padding:10px 20px;border-radius:14px;\n  }\n  .prize-desc{color:#94a3b8;font-size:.9rem;margin-top:10px;}\n  .date-line{color:#64748b;font-size:.82rem;margin-top:22px;}\n  .footer{color:#475569;font-size:.8rem;padding-bottom:30px;}\n  .spark{position:fixed;font-size:1.1rem;opacity:.5;animation:float 6s ease-in-out infinite;pointer-events:none;}\n  @keyframes float{0%,100%{transform:translateY(0);}50%{transform:translateY(-14px);}}\n</style>\n</head>\n<body>\n  <div class=\"gamosa-strip\" aria-hidden=\"true\"></div>\n  <span class=\"spark\" style=\"top:18%;left:8%;\">\u2728</span>\n  <span class=\"spark\" style=\"top:30%;right:10%;animation-delay:1.5s;\">\ud83c\udf89</span>\n  <span class=\"spark\" style=\"bottom:24%;left:12%;animation-delay:3s;\">\ud83c\udf8a</span>\n  <span class=\"spark\" style=\"bottom:30%;right:9%;animation-delay:2s;\">\u2728</span>\n\n  <div class=\"wrap\">\n    <span class=\"closed-pill\">\ud83c\udfc1 Contest Closed</span>\n    <h1>Picnic Moments Contest 2026</h1>\n    <p class=\"thanks\">\n      \u09aa\u09cd\u09f0\u09a4\u09bf\u09af\u09cb\u0997\u09bf\u09a4\u09be \u09b8\u09ae\u09be\u09aa\u09cd\u09a4 \u09b9\u09c8\u099b\u09c7\u0964 \u09b8\u0995\u09b2\u09cb \u0985\u0982\u09b6\u0997\u09cd\u09f0\u09b9\u09a3\u0995\u09be\u09f0\u09c0 \u0986\u09f0\u09c1 \u09ad\u09cb\u099f\u09be\u09f0\u09b8\u0995\u09b2\u0995\n      \u0986\u09a8\u09cd\u09a4\u09f0\u09bf\u0995 \u09a7\u09a8\u09cd\u09af\u09ac\u09be\u09a6! \u0986\u09aa\u09cb\u09a8\u09be\u09b2\u09cb\u0995\u09f0 \u09b8\u09b9\u09af\u09cb\u0997\u09f0 \u09ac\u09be\u09ac\u09c7\u0987 \u098f\u0987 \u0986\u09af\u09bc\u09cb\u099c\u09a8\u099f\u09cb \u09b8\u09ab\u09b2 \u09b9'\u09b2\u0964 \ud83d\ude4f\n    </p>\n\n    <div class=\"winner-card\">\n      <span class=\"winner-badge\">\ud83c\udfc6 WINNER</span>\n      <div class=\"photo-ring\">\n        <img src=\"data:image/jpeg;base64,\" alt=\"Winner \u2014 Sumon Roy\" />\n      </div>\n      <div class=\"winner-name\">Sumon Roy</div>\n      <div class=\"prize-line\">\ud83e\udd47 1st Prize \u2014 \u20b95,000</div>\n      <p class=\"prize-desc\">Best Picnic Moment</p>\n      <p class=\"date-line\">Declared by the Organizer \u2022 December 2026</p>\n    </div>\n  </div>\n\n  <p class=\"footer\">PicnicFest Contest Platform</p>\n</body>\n</html>";

app.get('/', (_req, res) => res.type('html').send(EMBEDDED_HTML));
app.get('/index.html', (_req, res) => res.type('html').send(EMBEDDED_HTML));
app.get('/healthz', (_req, res) => res.json({ ok: true, status: 'contest-closed' }));
app.use((_req, res) => res.redirect('/')); // any old link -> closed page

app.listen(PORT, '0.0.0.0', () => {
  console.log('PicnicFest (contest closed) listening on port ' + PORT);
});
